script>
(function(){
  var sel=document.getElementById('whatif');
  var out=document.getElementById('whatif-out');
  if(!sel||!out)return;
  var data={
    base:'Best: sell and reinvest. In the baseline selling leads renting in 43 of 50 real histories ten years after inheritance.',
    lowapp:'Home prices 3% a year: selling still leads ($8,110,630 vs $4,279,670 renting in 2076, 2026 dollars).',
    highstocks:'Stocks 10% a year: selling pulls far ahead ($22,029,930 vs $6,273,960 renting).',
    cash:'Proceeds in savings / T-bills at 3.5%: renting wins ($5,118,360 vs $3,554,580 selling).',
    phased:'Phased: 30 months in Treasuries (~4.4%) then into stocks - softer 1929/2008 crash entry, but gives up upside if stocks keep rising.'
  };
  var show=function(k){out.textContent=data[k];};
  show('base');
  sel.addEventListener('click',function(ev){
    var b=ev.target.closest('button');if(!b)return;
    sel.querySelectorAll('button').forEach(function(x){x.classList.toggle('on',x===b);});
    show(b.getAttribute('data-s'));
  });
})();
</script>
